import * as runtime from "@prisma/client/runtime/client";
const config = {
    "previewFeatures": [],
    "clientVersion": "7.10.0",
    "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
    "activeProvider": "postgresql",
    "inlineSchema": "// Prisma schema — Sistema de Control de Acceso, Terminal de Mollendo\n// Alcance base: ver Especificacion_Desarrollo_Control_Acceso_Mollendo_base.md (sección 8)\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------\n// Enums (reflejan los CHECK constraints del script SQL original)\n// ---------------------------------------------------------------------\n\nenum EstadoEmpresa {\n  activa\n  inactiva\n\n  @@map(\"estado_empresa\")\n}\n\nenum EstadoCuenta {\n  activo\n  baja\n\n  @@map(\"estado_cuenta\")\n}\n\n// Alcance base: un administrador único carga todo; Vigilancia solo consulta.\nenum RolUsuario {\n  administrador\n  vigilancia\n\n  @@map(\"rol_usuario\")\n}\n\nenum TipoDocumentoIdentidad {\n  DNI\n  CE\n  PASAPORTE\n\n  @@map(\"tipo_documento_identidad\")\n}\n\nenum EstadoPersona {\n  activo\n  inactivo\n\n  @@map(\"estado_persona\")\n}\n\nenum TipoMovimiento {\n  ingreso\n  salida\n\n  @@map(\"tipo_movimiento\")\n}\n\nenum ResultadoAcceso {\n  autorizado\n  denegado\n\n  @@map(\"resultado_acceso\")\n}\n\nenum AccionAuditoria {\n  crear\n  modificar\n  eliminar\n\n  @@map(\"accion_auditoria\")\n}\n\n// ---------------------------------------------------------------------\n// EMPRESA (proveedor / cliente, incluye OTP/MAS como una empresa más)\n// ---------------------------------------------------------------------\nmodel Empresa {\n  id                     Int           @id @default(autoincrement())\n  ruc                    String        @unique @db.VarChar(11)\n  razonSocial            String        @map(\"razon_social\") @db.VarChar(200)\n  correoContacto         String        @map(\"correo_contacto\") @db.VarChar(150)\n  telefonoContacto       String?       @map(\"telefono_contacto\") @db.VarChar(20)\n  estado                 EstadoEmpresa @default(activa)\n  contratoVigenciaInicio DateTime?     @map(\"contrato_vigencia_inicio\") @db.Date\n  contratoVigenciaFin    DateTime?     @map(\"contrato_vigencia_fin\") @db.Date\n  creadoEn               DateTime      @default(now()) @map(\"creado_en\")\n  actualizadoEn          DateTime      @default(now()) @updatedAt @map(\"actualizado_en\")\n\n  usuarios Usuario[]\n  personas Persona[]\n\n  @@map(\"empresa\")\n}\n\n// ---------------------------------------------------------------------\n// USUARIO (administrador o vigilancia — personal interno de OTP/MAS)\n// Sin invitación por correo: las cuentas las crea el administrador.\n// ---------------------------------------------------------------------\nmodel Usuario {\n  id           Int          @id @default(autoincrement())\n  empresaId    Int          @map(\"empresa_id\")\n  empresa      Empresa      @relation(fields: [empresaId], references: [id])\n  rol          RolUsuario\n  correo       String       @unique @db.VarChar(150)\n  passwordHash String       @map(\"password_hash\") @db.VarChar(255)\n  estadoCuenta EstadoCuenta @default(activo) @map(\"estado_cuenta\")\n  creadoEn     DateTime     @default(now()) @map(\"creado_en\")\n\n  auditorias Auditoria[]\n\n  @@index([empresaId])\n  @@map(\"usuario\")\n}\n\n// ---------------------------------------------------------------------\n// PERSONA (trabajador). Alcance base: sin perfiles ni puestos — el\n// administrador registra empresa, trabajador y documentos, nada más.\n// ---------------------------------------------------------------------\nmodel Persona {\n  id                     Int                    @id @default(autoincrement())\n  empresaId              Int                    @map(\"empresa_id\")\n  empresa                Empresa                @relation(fields: [empresaId], references: [id])\n  tipoDocumentoIdentidad TipoDocumentoIdentidad @map(\"tipo_documento_identidad\")\n  numeroDocumento        String                 @map(\"numero_documento\") @db.VarChar(20)\n  nombres                String                 @db.VarChar(150)\n  apellidos              String                 @db.VarChar(150)\n  // Foto para el reconocimiento facial del terminal ZKTeco (ruta en disco).\n  fotoUrl                String?                @map(\"foto_url\") @db.VarChar(500)\n  estado                 EstadoPersona          @default(activo)\n  creadoEn               DateTime               @default(now()) @map(\"creado_en\")\n\n  documentos    DocumentoPersona[]\n  eventosAcceso EventoAcceso[]\n\n  // Global: una persona pertenece a una sola empresa a la vez\n  @@unique([tipoDocumentoIdentidad, numeroDocumento])\n  @@index([empresaId])\n  @@index([numeroDocumento])\n  @@map(\"persona\")\n}\n\n// ---------------------------------------------------------------------\n// TIPO_DOCUMENTO (nombres de documento: SCTR, Inducción, etc.). El\n// administrador los agrega al subir un documento. Si un documento vence o no\n// lo define su fecha de vencimiento (vacía = no vence).\n// ---------------------------------------------------------------------\nmodel TipoDocumento {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique @db.VarChar(100)\n\n  documentos DocumentoPersona[]\n\n  @@map(\"tipo_documento\")\n}\n\n// ---------------------------------------------------------------------\n// DOCUMENTO_PERSONA (historial completo, nunca se borra)\n// Alcance base: sin aprobación — lo carga el administrador y ya es válido.\n// La vigencia se calcula contra fechaVencimiento; cuenta la última versión.\n// ---------------------------------------------------------------------\nmodel DocumentoPersona {\n  id               Int           @id @default(autoincrement())\n  personaId        Int           @map(\"persona_id\")\n  persona          Persona       @relation(fields: [personaId], references: [id])\n  tipoDocumentoId  Int           @map(\"tipo_documento_id\")\n  tipoDocumento    TipoDocumento @relation(fields: [tipoDocumentoId], references: [id])\n  fechaEmision     DateTime?     @map(\"fecha_emision\") @db.Date\n  fechaVencimiento DateTime?     @map(\"fecha_vencimiento\") @db.Date\n  archivoUrl       String?       @map(\"archivo_url\") @db.VarChar(500)\n  version          Int           @default(1)\n  creadoEn         DateTime      @default(now()) @map(\"creado_en\")\n\n  @@index([personaId])\n  @@index([personaId, tipoDocumentoId, version])\n  @@map(\"documento_persona\")\n}\n\n// ---------------------------------------------------------------------\n// EVENTO_ACCESO (ingreso / salida por torniquete)\n// Booleanos de denegación en vez de un solo motivo: un evento puede\n// denegarse por alcohol y documentos a la vez, y una baja deniega de\n// inmediato sin evaluar lo demás. Sin antipassback (alcance base): la\n// salida siempre se registra como autorizada.\n// ---------------------------------------------------------------------\nmodel EventoAcceso {\n  id                    Int             @id @default(autoincrement())\n  personaId             Int             @map(\"persona_id\")\n  persona               Persona         @relation(fields: [personaId], references: [id])\n  tipoMovimiento        TipoMovimiento  @map(\"tipo_movimiento\")\n  resultado             ResultadoAcceso\n  denegadoPorBaja       Boolean         @default(false) @map(\"denegado_por_baja\")\n  denegadoPorAlcohol    Boolean         @default(false) @map(\"denegado_por_alcohol\")\n  denegadoPorDocumentos Boolean         @default(false) @map(\"denegado_por_documentos\")\n  denegadoSinDocumentos Boolean         @default(false) @map(\"denegado_sin_documentos\")\n  fechaHora             DateTime        @default(now()) @map(\"fecha_hora\")\n  torniqueteId          String?         @map(\"torniquete_id\") @db.VarChar(50)\n\n  @@index([personaId, fechaHora])\n  @@map(\"evento_acceso\")\n}\n\n// ---------------------------------------------------------------------\n// AUDITORIA (quién creó/modificó/aprobó cada registro)\n// ---------------------------------------------------------------------\nmodel Auditoria {\n  id            Int             @id @default(autoincrement())\n  usuarioId     Int?            @map(\"usuario_id\")\n  usuario       Usuario?        @relation(fields: [usuarioId], references: [id])\n  tablaAfectada String          @map(\"tabla_afectada\") @db.VarChar(50)\n  registroId    Int             @map(\"registro_id\")\n  accion        AccionAuditoria\n  fechaHora     DateTime        @default(now()) @map(\"fecha_hora\")\n\n  @@index([tablaAfectada, registroId])\n  @@map(\"auditoria\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
